	{surface: "AGENT_*/DDX_AGENT_*", re: regexp.MustCompile(`\b(?:DDX_AGENT|AGENT)_[A-Z0-9_]+\b`)},
}

var skippedDirs = map[string]bool{
	".git":                 true,
	".ddx":                 true,
	".agents":              true,
	".claude":              true,
	".helix-ratchets":      true,
	"docs/helix":           true,
	"docs/research":        true,
	"internal/renamecheck": true,
	// DDX_AGENT_* harness env vars are not yet renamed; allowlisted until a
	// dedicated harness-rename bead updates them.
	"internal/harnesses": true,
}

var skippedFiles = map[string]bool{
	"CHANGELOG.md": true,
	// Historical benchmark subset v1 is a documented placeholder artifact retained
	// per CL-004.09 / docs/research/scripts-fixtures-assets-cleanup-inventory-2026-04-30.md.
	// Its header comment preserves the original creation date and old product name as
	// historical evidence; no active code generates or consumes the product-name string.
	"scripts/benchmark/task-subset-v1.yaml": true,
	// Root-level service test files that reference DDX_AGENT_* harness env vars
	// which have not yet been renamed. Allowlisted until the harness-rename bead
	// is complete.
	"harness_golden_integration_test.go": true,
	"service_providers_test.go":          true,
	"service_route_attempts_test.go":     true,
	"service_status_test.go":             true,
}

func Scan(opts Options) ([]Finding, error) {
	root := opts.Root
	if root == "" {
		root = "."
	}

	var findings []Finding
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if rel == "." {
			return nil
		}
		if d.IsDir() {
			if shouldSkipDir(rel) {
				return filepath.SkipDir
			}
			return nil
		}
		if skippedFiles[rel] {
			return nil
		}
		if !isTextCandidate(rel) {
			return nil
		}
		fileFindings, err := scanFile(root, rel)
		if err != nil {
			return err
		}
		findings = append(findings, fileFindings...)
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Slice(findings, func(i, j int) bool {
		if findings[i].Path != findings[j].Path {
			return findings[i].Path < findings[j].Path
		}
		if findings[i].Line != findings[j].Line {
			return findings[i].Line < findings[j].Line
		}
		return findings[i].Column < findings[j].Column
	})
	return findings, nil
}

func Report(w io.Writer, findings []Finding) error {
	if w == nil {
		return nil
	}
	if len(findings) == 0 {
		_, err := fmt.Fprintln(w, "rename-noise: no unallowlisted old-name hits found")
		return err
	}
	if _, err := fmt.Fprintf(w, "rename-noise: %d unallowlisted old-name hit(s)\n", len(findings)); err != nil {
		return err
	}
	for _, f := range findings {
